    ok(mg.ok && mg.stats.watertight && mg.stats.volumeMm3 > 0 && mg.stats.size[0] > 40 && Math.abs(mg.stats.size[0] - 44.6) < 2 && mg.mesh.f.length === mg.stats.triangles * 3, 'a gear builds into a closed solid of the right size');
    const area = 100 * 80 - (4 - Math.PI) * 36 - 12 * Math.PI * 1.7 * 1.7; ok(mp.ok && Math.abs(mp.stats.volumeMm3 - area * 4) / (area * 4) < 0.01 && mp.stats.watertight, 'a plate with twelve holes has the volume you would work out by hand');
