    rr = await H('POST', '/studio/slice', { part: { name: 'Gear', type: 'spur_gear', params: { module: 1.5, teeth: 24, thickness: 6, bore: 5 } }, settings: { infillPct: 0 } }); ok(rr.s === 200 && rr.j.layers === 30, 'a gear slices, with no infill when you ask for none');
